type Table = any;
type Page<T = any> = Array<T>;
type Db = {
  [name: string]: any;
  get(target: any, key: any): any;
  exists(target: any, key: any): boolean;
  scan(target: any, prefix: any, options?: Record<string, any>): Page;
  insert(target: any, row: any): any;
  update(target: any, key: any, patch: Record<string, any> | ((row: any) => Record<string, any>)): void;
  upsert(target: any, key: any, row: Record<string, any> | ((row: any) => Record<string, any>)): void;
  delete(target: any, key: any): void;
  require(condition: any, code?: string): void;
  assert(condition: any): void;
};
type Context = { db: Db; ctx: { [name: string]: any; viewer: any; now(): any; newId(): any }; args: Record<string, any> };
type Arg<T = any> = { readonly __value?: T };
type ArgsOf<A extends Record<string, Arg<any>>> = { [K in keyof A]: A[K] extends Arg<infer T> ? T : never };
declare function table(name: string): any;
declare function privateTable(name: string): any;
declare function maintained(name: string, source: any): any;
declare function scalar(): Arg<any>;
declare function id(table?: any): Arg<any>;
declare function text(options?: { max?: number } | number): Arg<string>;
declare function int(): Arg<number>;
declare function time(): Arg<number>;
declare function optional<T>(value: Arg<T>): Arg<T | undefined>;
declare function list<T>(value: Arg<T>, options: { max: number }): Arg<T[]>;
declare function query<A extends Record<string, Arg<any>>>(args: A, handler: (context: Omit<Context, "args"> & { args: ArgsOf<A> }) => any): any;
declare function mutation<A extends Record<string, Arg<any>>>(args: A, handler: (context: Omit<Context, "args"> & { args: ArgsOf<A> }) => any): any;
declare function range(start: number, end: number): number[];
declare function mentionTokens(value: string): string[];
declare function deterministicShare(amount: number, recipients: any[], recipient: any): number;
declare function concat(...values: any[]): any;
declare function max(...values: any[]): any;
declare function min(...values: any[]): any;
declare function divmod(value: number, divisor: number): any;
declare function recurse(seed: any, step: (value: any) => any, options: { depth: number; fanout: number }): any[];

